import { useEffect, useMemo } from 'react';
import { DynamicAnalyticsCore, DynamicAnalyticsCoreOptions, DynamicEvent } from '../lib/dynamic-analytics-core';

export interface UseDynamicAnalyticsOptions extends DynamicAnalyticsCoreOptions {
  /** Called whenever a trackable event (or, when `errorTrackingEnabled` is true, a failure) is emitted. */
  onEvent?: (event: DynamicEvent) => void;
}

/**
 * React hook that creates and owns a {@link DynamicAnalyticsCore} instance for the lifetime of the
 * calling component. The instance is memoized (stable identity across re-renders), `onEvent` (if
 * provided) is subscribed/unsubscribed automatically, and `destroy()` is called on unmount.
 *
 * @example
 * ```tsx
 * function App() {
 *   const analytics = useDynamicAnalytics({
 *     onEvent: event => sendToAnalyticsBackend(event),
 *   });
 *
 *   useEffect(() => {
 *     analytics.initializeWithConfig(config, (min, max) => isVersionCompatible(min, max));
 *   }, [analytics]);
 *
 *   return <div>...</div>;
 * }
 * ```
 */
export function useDynamicAnalytics(options: UseDynamicAnalyticsOptions = {}): DynamicAnalyticsCore {
  const { onEvent, ...coreOptions } = options;

  // eslint-disable-next-line react-hooks/exhaustive-deps -- intentionally created once per component instance
  const analytics = useMemo(() => new DynamicAnalyticsCore(coreOptions), []);

  useEffect(() => {
    if (!onEvent) {
      return undefined;
    }
    const subscription = analytics.onEvent.subscribe(onEvent);
    return () => subscription.unsubscribe();
  }, [analytics, onEvent]);

  useEffect(() => {
    return () => analytics.destroy();
  }, [analytics]);

  return analytics;
}
